{
  "file_name": "SoftCartoonCloud",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// Simple circle SDF: negative inside, positive outside
float sdCircle(float2 p, float r)
{
    return length(p) - r;
}

// Smooth union between two SDFs
float opSmoothUnion(float d1, float d2, float k)
{
    k = max(k, 1e-6);
    float h = saturate(0.5 + 0.5 * (d2 - d1) / k);
    return lerp(d2, d1, h) - k * h * (1.0 - h);
}

void FunctionName_float(
    float2 UV,
    float Size,
    float2 Jitter1,
    float2 Jitter2,
    float4 Color,
    out float4 outColor)
{
    // PLAN:
    // 1) Map UV to centered coordinates around (0.5,0.5) and scale by Size.
    // 2) Place several circle SDF "bumps" with slight horizontal offsets and jitters.
    // 3) Combine them using smooth unions to form an organic cloud silhouette.
    // 4) Use smoothstep for anti-aliased soft edges.
    // 5) Output single fill Color with alpha = mask for soft cartoon cloud.
    // USER REQUEST: A soft cartoon-style cloud made from multiple rounded bumps. The cloud should feel organic, not perfectly symmetric. Overall size should be adjustable. Single fill color with smooth edges.

    // Center UV coordinates and scale by overall Size (0.5 ≈ half screen)
    float2 centered = UV - float2(0.5, 0.5);
    float safeSize = max(Size, 1e-3);
    centered /= safeSize;

    // Base positions for cloud bumps in local space
    float2 p = centered;

    // Core bump positions (asymmetric for organic feel)
    float2 c0 = float2(-0.45, -0.05) + Jitter1 * 0.2;
    float2 c1 = float2(-0.10,  0.10);
    float2 c2 = float2( 0.25,  0.00) + Jitter2 * 0.2;
    float2 c3 = float2( 0.55, -0.05);
    float2 c4 = float2( 0.05, -0.18);

    // Radii for bumps (slightly varied)
    float r0 = 0.45;
    float r1 = 0.55;
    float r2 = 0.50;
    float r3 = 0.38;
    float r4 = 0.42;

    // Compute SDFs for each bump
    float d0 = sdCircle(p - c0, r0);
    float d1 = sdCircle(p - c1, r1);
    float d2 = sdCircle(p - c2, r2);
    float d3 = sdCircle(p - c3, r3);
    float d4 = sdCircle(p - c4, r4);

    // Smoothly union all bumps to form the cloud
    float k = 0.25; // smoothing factor for unions
    float d = d0;
    d = opSmoothUnion(d, d1, k);
    d = opSmoothUnion(d, d2, k);
    d = opSmoothUnion(d, d3, k);
    d = opSmoothUnion(d, d4, k);

    // Anti-aliased edge mask (inside = 1, outside = 0)
    float edge = smoothstep(0.01, -0.01, d);

    // Final color with smooth alpha
    float mask = edge;
    outColor = float4(Color.rgb * mask, mask);
}
