  "hlsl": "float sdCircle(float2 p, float r)
{
    return length(p) - r;
}

float4 CloudShader(float2 uv, float4 Size, float4 Jitter1, float4 Jitter2, float4 Color) : SV_Target
{
    // Normalize UV to -1..1 space
    float2 p = uv * 2.0 - 1.0;
    p.x *= 1.5;

    // Cloud overall radius from Size.x
    float baseR = Size.x;

    // Define organic, non-symmetric bump centers
    float2 c0 = float2(0.0, 0.0);
    float2 c1 = float2(-0.45, 0.05) + Jitter1.xy;
    float2 c2 = float2(0.45, 0.02) + Jitter2.xy;
    float2 c3 = float2(-0.15, -0.18);
    float2 c4 = float2(0.25, -0.16);

    // Radii for each bump (scaled by Size)
    float r0 = baseR * 0.9;
    float r1 = baseR * 0.7;
    float r2 = baseR * 0.75;
    float r3 = baseR * 0.6;
    float r4 = baseR * 0.55;

    float d0 = sdCircle(p - c0, r0);
    float d1 = sdCircle(p - c1, r1);
    float d2 = sdCircle(p - c2, r2);
    float d3 = sdCircle(p - c3, r3);
    float d4 = sdCircle(p - c4, r4);

    // Smooth union of bumps
    float k = 0.3 * baseR;
    float d = d0;

    float h1 = saturate(0.5 + 0.5 * (d1 - d) / k);
    d = lerp(d1, d, h1) - k * h1 * (1.0 - h1);

    float h2 = saturate(0.5 + 0.5 * (d2 - d) / k);
    d = lerp(d2, d, h2) - k * h2 * (1.0 - h2);

    float h3 = saturate(0.5 + 0.5 * (d3 - d) / k);
    d = lerp(d3, d, h3) - k * h3 * (1.0 - h3);

    float h4 = saturate(0.5 + 0.5 * (d4 - d) / k);
    d = lerp(d4, d, h4) - k * h4 * (1.0 - h4);

    // Soft edge
    float edge = fwidth(d) * 1.5;
    float alpha = smoothstep(0.0, -edge, d);

    float3 col = Color.rgb;
    return float4(col, alpha * Color.a);
}"
}

