{
  "file_name": "CrescentMoonShape",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// Simple circle SDF: distance from point to circle surface (negative inside)
float sdCircle(float2 p, float radius)
{
    return length(p) - radius;
}

// Boolean subtraction for SDFs: a minus b
float opSubtract(float dA, float dB)
{
    return max(dA, -dB);
}

void FunctionName_float(float2 UV, float Radius, float Thickness, float InnerOffset, float4 Color, out float4 outColor)
{
    // User request: A crescent moon shape created by cutting one circle out of another.

    // PLAN:
    // 1) Map UV to centered coordinates around (0.5, 0.5) and scale by Radius.
    // 2) Compute outer circle SDF (main disk of the moon).
    // 3) Compute inner circle SDF shifted horizontally by InnerOffset to carve out the crescent.
    // 4) Crescent SDF = opSubtract(outer, inner).
    // 5) Use smoothstep for anti-aliased edge, modulate by Thickness, and output solid Color.

    // 1) Center UV and scale by Radius to control overall size
    float2 centered = UV - 0.5;
    float safeRadius = max(Radius, 1e-4);
    float2 p = centered / safeRadius;

    // 2) Outer circle SDF (unit space, will be scaled by Radius via p)
    float dOuter = sdCircle(p, 1.0);

    // 3) Inner circle SDF, shifted to cut a crescent
    // Inner radius controls thickness of the crescent: clamp Thickness to [0, 0.99]
    float t = clamp(Thickness, 0.0, 0.99);
    float innerRadius = 1.0 * (1.0 - t);
    float shift = InnerOffset; // positive shift moves the cutting circle to the right
    float2 pInner = p + float2(shift, 0.0);
    float dInner = sdCircle(pInner, innerRadius);

    // 4) Crescent SDF via subtraction
    float dCrescent = opSubtract(dOuter, dInner);

    // 5) Anti-aliased edge and final color
    // Use a fixed AA width in normalized space, then scaled by Radius for consistency
    float aa = 0.01;
    float edge = smoothstep(aa, -aa, dCrescent);

    // Output with solid fill color and alpha = edge
    outColor = float4(Color.rgb * edge, edge);
}
