void FunctionName_float(float2 UV, float Radius, float Thickness, float InnerOffset, float4 Color, out float4 outColor)
{
    // Center UV around (0.5, 0.5) and scale by Radius to control overall size
    float2 centered = UV - 0.5;
    float safeRadius = max(Radius, 1e-4);
    float2 p = centered / safeRadius;

