// MAIN
// Eight-pointed star with long sharp spikes.
// - Fixed 8 points
// - Adjustable spike length
// - Adjustable rotation
// - Single fill color
void FunctionName_float(float2 UV, float Size, float SpikeLength, float Rotation, float4 Color, out float4 outColor)
{
    // Center UV to [-0.5, 0.5] and apply size
    float2 p = (UV - 0.5) / max(Size, 1e-4);

    // Global rotation of the star
    p = rotate2D(p, Rotation);

    // Parameters in local space
    float coreRadius = 0.18;              // radius of inner (roundish) area
    float spikeLen   = clamp(SpikeLength, 0.0, 1.6); // radial extension of spikes

    // Convert to polar coordinates
    float r = length(p);
    float ang = atan2(p.y, p.x);  // [-PI, PI]

    // Tile angle into 8 sectors (N=8)
    const float N = 8.0;
    float sectorAngle = 2.0 * PI / N;          // full angle of a sector

    // Fold the angle into one canonical wedge around 0
    float a = abs(fmod(ang + 0.5 * sectorAngle, sectorAngle) - 0.5 * sectorAngle);

    // Angle at which the spike sides meet the core
    // Smaller values = sharper, more elongated points
    float spikeAperture = 0.18; // in radians; controls sharpness of each spike

    // Base radius is the core; beyond that the radius grows toward the spike tip
    float baseR = coreRadius;

    // Shape of radial envelope forming a sharp spike
    // When a = 0 (center of spike), we get full spikeLen.
    // As a approaches spikeAperture, the extra radius goes to 0.
    float angularFactor = saturate(1.0 - a / spikeAperture);
    float extra = spikeLen * angularFactor;

    // Final radius of the star boundary at this angle
    float boundaryR = baseR + extra;

    // Signed distance field: inside negative, outside positive
    float d = r - boundaryR;

    // Anti-aliased edge
    float aa = fwidth(d) * 0.75;
    float mask = smoothstep(aa, -aa, d);

    outColor = float4(Color.rgb, 1.0) * mask;
}
