// Signed distance from point p to an infinite line defined by origin o and unit direction dir
float sdLine(float2 p, float2 o, float2 dir)
{
    float2 v = p - o;
    float proj = dot(v, dir);
    float2 closest = o + dir * proj;
    return length(p - closest);
}

void FunctionName_float(
    float2 UV,
    float Radius,
    float Turns,
    float Thickness,
    float4 Color,
    out float4 outColor)
{
    // User request: A spiral shape growing outward from the center with adjustable turns, thickness, and solid color.
    // PLAN:
    // 1) Center UV at (0.5, 0.5) and optionally scale by Radius.
    // 2) Convert to polar coordinates: radius r and angle a.
    // 3) Define a target spiral radius rSpiral(a) = k * a for a in [0, Turns * 2π].
    // 4) For each pixel, project onto nearest angle a0 in spiral domain, compute distance to local straight approximation.
    // 5) Use an SDF-like distance to the spiral line, apply smoothstep for anti-aliasing, and output color.

    // 1) Center UV coordinates
    float2 centered = UV - 0.5;

    // Treat Radius as a uniform scale for the whole spiral (0.5 ~ half screen)
    float scale = max(Radius, 0.001);
    centered /= scale;

    // 2) Polar coordinates
    float r = length(centered);
    float angle = atan2(centered.y, centered.x); // range [-PI, PI]
    if (angle < 0.0)
    {
        angle += 2.0 * PI;
    }

    // 3) Spiral definition
    float totalAngle = max(Turns, 0.0) * 2.0 * PI;

    // If no turns, just output transparent
    if (totalAngle <= 0.0001)
    {
        outColor = float4(0.0, 0.0, 0.0, 0.0);
        return;
    }

    // Archimedean spiral: r = k * a
    float k = 1.0 / max(totalAngle, 0.0001);

    // 4) Find local straight-line approximation of spiral near this point
    float a0 = clamp(angle, 0.0, totalAngle);
    float r0 = k * a0;

    // Spiral point at angle a0
    float2 s0 = float2(cos(a0), sin(a0)) * r0;

    // Derivative dr/da = k; spiral tangent direction in Cartesian
    float2 tangent = float2(
        -r0 * sin(a0) + k * cos(a0),
         r0 * cos(a0) + k * sin(a0));
    float2 dir = normalize(tangent);

    // Signed distance to local spiral line approximation
    float dist = sdLine(centered, s0, dir);

    // 5) Thickness and anti-aliasing
    float halfThickness = 0.5 * max(Thickness, 0.0001);
    float sdf = dist - halfThickness;

    // Prevent drawing beyond the spiral's end by fading outside valid angle and radius
    float maxRadius = k * totalAngle;
    float radialFade = smoothstep(maxRadius + halfThickness, maxRadius - halfThickness, r);
    float angularFade = smoothstep(totalAngle + 0.1, totalAngle - 0.1, a0);
    float domainMask = radialFade * angularFade;

    // Anti-aliased edge
    float edge = smoothstep(0.01, -0.01, sdf) * domainMask;

    // Output with smooth alpha
    outColor = float4(Color.rgb * edge, edge);
}
