{
  "code": "#ifndef PI
#define PI 3.14159265359
#endif

void FunctionName_float(
    float2 UV,
    float Radius,
    float Turns,
    float Thickness,
    float4 Color,
    out float4 outColor)
{
    // Center UV at (0.5, 0.5) and normalize by Radius
    float2 p = (UV - 0.5) / max(Radius, 1e-4);

    float r = length(p);

    // Early out if no visible spiral domain
    if (Turns <= 0.0 || r <= 0.0)
    {
        outColor = float4(0, 0, 0, 0);
        return;
    }

    float totalAngle = Turns * 2.0 * PI;
    float k = 1.0 / max(totalAngle, 1e-4); // Archimedean spiral: r = k * a

    // --- Robust closest-point search along the spiral ---
    // Convert point to polar angle in [0, 2PI)
    float angle = atan2(p.y, p.x);
    if (angle < 0.0)
        angle += 2.0 * PI;

    // Initial guess: match current angle, clamped to spiral domain
    float a = clamp(angle, 0.0, totalAngle);

    // Newton iteration to minimize distance between p and spiral(a)
    [unroll]
    for (int i = 0; i < 8; i++)
    {
        float rSp = k * a;
        float ca = cos(a);
        float sa = sin(a);
        float2 s = float2(ca, sa) * rSp;      // point on spiral
        float2 d = s - p;                     // vector from p to spiral

        // Tangent of spiral: t(a) = (dr/da * dir + r * dir_perp)
        float drda = k;
        float2 tangent = float2(-rSp * sa + drda * ca,
                                 rSp * ca + drda * sa);

        // Project gradient-based update (1D Newton step)
        float num = dot(d, tangent);
        float den = dot(tangent, tangent) + 1e-6;
        a -= num / den;
        a = clamp(a, 0.0, totalAngle);
    }

    // Final closest point after iterations
    float rSpiral = k * a;
    float2 sFinal = float2(cos(a), sin(a)) * rSpiral;
    float dist = length(p - sFinal);

    // Thickness control (in normalized space)
    float halfThickness = 0.5 * max(Thickness, 1e-4);
    float sdf = dist - halfThickness;

    // Restrict drawing to spiral domain: radius grows from 0 to k*totalAngle
    float maxRadius = k * totalAngle;
    float domainMask = step(0.0, rSpiral) * step(rSpiral, maxRadius);

    // Anti-aliased edge
    float aa = fwidth(sdf);
    float edge = 1.0 - smoothstep(-aa, aa, sdf);
    edge *= domainMask;

    outColor = float4(Color.rgb * edge, edge);
}
