    float halfSector = 0.5 * sectorAngle;
    float k = round(angle / sectorAngle);
    float foldedAngle = angle - k * sectorAngle;

    // Rotate point so active branch is aligned to +Y axis
    float2 pBranch = rotate2D(p, -foldedAngle);

