    float2 centered = UV - 0.5;
    float s = max(Size, 0.001);
    float2 p = centered / s;

    float r = length(p);
    float angle = atan2(p.y, p.x); // -PI..PI

    // 2) Angular repetition: fold into [0, sectorAngle]
    float n = max(BranchCount, 1.0);
    float sectorAngle = 2.0 * PI / n;

    // Map angle to [0, 2PI)
    float ang = angle;
    if (ang < 0.0) ang += 2.0 * PI;

    // Fold angle into first sector [0, sectorAngle]
    ang = fmod(ang, sectorAngle);

    // Reflect around sector center so branch is symmetric around its axis
    float halfSector = 0.5 * sectorAngle;
    float localAngle = abs(ang - halfSector);

    // 3) Convert back to a canonical branch coordinate system (branch along +Y)
    // pBranch carries full 2D info, preserving distance from the axis via x.
    float2 pBranch = float2(sin(localAngle) * r, cos(localAngle) * r);

    // Adjustable thickness
    float thickness = max(BranchThickness, 0.01);

    // Main branch (vertical bar in branch space)
    float halfWidth = thickness;
    float halfLength = 1.2;       // overall length of main branch
    float mainOffsetY = 0.4;      // shift so center looks balanced
    float dMain = sdBox(pBranch - float2(0.0, mainOffsetY), float2(halfWidth, halfLength));

    // Side twigs: several pairs along the main branch
    float dTwigs = 1e5;

    // Parameters controlling twig placement relative to main branch
    float twigWidth = thickness * 0.7;
    float twigLenBase = 0.55;
    float twigAngle = 0.5;        // ~28.6 degrees

