    float maxRadius = 1.7;
    float dRadius = r - maxRadius;
    float d = max(dBranch, dRadius);

    // 5) Anti-aliased edge and final color
    float edge = smoothstep(0.01, -0.01, d);
    float mask = edge;

    outColor = float4(Color.rgb * mask, mask);
}
