float4 RenderSnowflake(float2 uv, float4 Size, float4 BranchCount, float4 BranchThickness, float4 Color)
{
    float2 p = uv;
    float r = length(p);
    float baseRadius = Size.x;
    if (r > baseRadius * 1.05)
    {
        return float4(0, 0, 0, 0);
    }

    float n = max(1.0, BranchCount.x);
    float angle = atan2(p.y, p.x);
    float sectorAngle = 2.0 * 3.14159265 / n;
    float halfSector = sectorAngle * 0.5;

    angle = fmod(angle + 3.14159265, 2.0 * 3.14159265) - 3.14159265;
    float k = floor((angle + halfSector) / sectorAngle);
    angle = angle - k * sectorAngle;

    float2 dir = float2(cos(0.0), sin(0.0));
    float2 a = float2(0.0, 0.0);
    float2 b = dir * baseRadius;

    float thickness = BranchThickness.x;
    float d = sdSegment(p, a, b) - thickness;

    float spikeCount = 3.0;
    for (int i = 1; i <= 3; ++i)
    {
        float t = (float)i / (spikeCount + 1.0);
        float2 c = dir * baseRadius * t;
        float sideLen = baseRadius * 0.25;

        float sideAngle = 0.35;
        float2 dirL = float2(cos(sideAngle), sin(sideAngle));
        float2 dirR = float2(cos(-sideAngle), sin(-sideAngle));

        float dL = sdSegment(p, c, c + dirL * sideLen) - thickness * 0.7;
        float dR = sdSegment(p, c, c + dirR * sideLen) - thickness * 0.7;

        d = min(d, min(dL, dR));
    }

    float alpha = saturate(-d * 40.0 + 1.0);
    float4 col = Color;
    col.a *= alpha;

    return col;
}"
}

