  "hlsl": "float4 ArrowRight(float2 uv, float ShaftLength, float ShaftThickness, float ArrowHeadSize, float4 Color)
{
    // Normalize UV to centered coordinates (-0.5..0.5)
    float2 p = uv - 0.5;

    // Clamp parameters to reasonable ranges
    float shaftLen = saturate(ShaftLength);
    float shaftThick = saturate(ShaftThickness);
    float headSize = saturate(ArrowHeadSize);

    // Total arrow length kept within 0..1 in UV space
    float totalLen = saturate(shaftLen + headSize);

    // Scale to keep arrow centered and readable
    float scale = 0.8; // overall size
    p *= scale;

    // Recompute effective lengths in scaled space
    float bodyLen = totalLen * 0.6;
    float tipLen = totalLen * 0.4;

    // Shaft is a horizontal rectangle centered vertically
    float halfThick = lerp(0.03, 0.25, shaftThick);
    float shaftStart = -bodyLen * 0.5;
    float shaftEnd   = shaftStart + bodyLen;

    bool inShaft = (p.x >= shaftStart) && (p.x <= shaftEnd) && (abs(p.y) <= halfThick);

    // Arrowhead is a triangle on the right side
    float headBaseX = shaftEnd;
    float headTipX  = headBaseX + tipLen;

    // Only consider points to the right of the base of the head
    bool inHeadX = (p.x >= headBaseX) && (p.x <= headTipX);

    // Normalized position from base (0) to tip (1)
    float t = 0.0;
    if (headTipX != headBaseX)
        t = (p.x - headBaseX) / (headTipX - headBaseX);

    // Arrowhead height scales with parameter
    float headHeight = lerp(0.15, 0.45, headSize);

    // For a right-pointing isosceles triangle, vertical extent shrinks linearly towards the tip
    float allowedY = (1.0 - t) * headHeight;
    bool inHeadY = abs(p.y) <= allowedY;

    bool inHead = inHeadX && inHeadY;

    bool inside = inShaft || inHead;

    float alpha = inside ? 1.0 : 0.0;

    return float4(Color.rgb, Color.a * alpha);
}
