{
    // Normalize UV to a centered coordinate system: (0,0) in the middle, range roughly [-1,1]
    float2 p = (uv - 0.5) * 2.0;

    // Clamp and sanitize parameters
    ShaftLength = saturate(ShaftLength);          // 0..1 in normalized space
    ShaftThickness = saturate(ShaftThickness);    // 0..1, relative to full height
    ArrowHeadSize = saturate(ArrowHeadSize);      // 0..1 of total width

    // Ensure non-degenerate values
    ShaftLength = max(ShaftLength, 0.05);
    ShaftThickness = max(ShaftThickness, 0.02);
    ArrowHeadSize = max(ArrowHeadSize, 0.05);

    // The arrow extends horizontally from left to right, centered vertically.
    // Total visual width = ShaftLength + ArrowHeadSize in normalized coordinates.
    float totalWidth = ShaftLength + ArrowHeadSize;

    // Keep arrow centered: shift so that its center is at x = 0.
    // Arrow base (tail) starts at x = -totalWidth * 0.5
    float xStart = -totalWidth * 0.5;
    float xShaftEnd = xStart + ShaftLength;       // where the shaft ends and head begins
    float xHeadTip = xStart + totalWidth;         // tip of the head (rightmost point)

    // Shaft is a horizontal rectangle
    float halfThickness = ShaftThickness * 0.5;
    bool inShaft = (p.x >= xStart) && (p.x <= xShaftEnd) && (abs(p.y) <= halfThickness);

    // Arrowhead is a right-pointing triangle
    // Triangle base along xShaftEnd, spanning vertically from -halfThickness to +halfThickness
    // Tip at (xHeadTip, 0)
    bool inHead = false;
    if (p.x >= xShaftEnd && p.x <= xHeadTip)
    {
        float t = (p.x - xShaftEnd) / (xHeadTip - xShaftEnd + 1e-6);
        float allowedY = lerp(halfThickness, 0.0, t);
        inHead = abs(p.y) <= allowedY;
    }

    bool inside = inShaft || inHead;

    if (!inside)
    {
        return float4(0, 0, 0, 0);
    }

    return Color;
}
